-- ACTUALIZACION INCREMENTAL GDC — pagos de "Estado Financiero Cuotas GDC 2026 a julio actualizada.xlsx"
-- Generado 2026-08-13T03:27:22.983Z.
-- Alcance: SOLO agrega el incremento real detectado contra
-- "Estado Finaciero Cuotas GDC 2026.xlsx" (version ya cargada anteriormente).
-- Corrige ademas el valor de mayo de 24692998-K a 60.000 (confirmado por el
-- cliente; el archivo actualizado traia 30.000 por error de digitacion — ese
-- valor NO se toca aqui porque ya deberia existir en la BD desde antes).
--
-- Personas afectadas: 72
-- Periodos-cuota con monto nuevo: 501
-- Periodos-cuota con puntaje nuevo: 493
-- Monto total incremental: $5.946.000
-- Puntaje total incremental: 4950
--
-- SEGURIDAD: cada INSERT esta protegido por NOT EXISTS contra la cuota real en
-- el momento de ejecutar. Si una cuota ya aparece pagada o con pago_detalle
-- previo, esa fila especifica se salta silenciosamente (no duplica fondos).
-- Ejecutar primero un respaldo completo (phpMyAdmin -> Exportar) antes de
-- correr este script, ademas de las tablas de respaldo que este mismo script
-- crea.

SET NAMES utf8mb4;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';

CREATE TABLE IF NOT EXISTS respaldo_incremental_20260812_pagos LIKE pagos;
CREATE TABLE IF NOT EXISTS respaldo_incremental_20260812_pago_detalle LIKE pago_detalle;
CREATE TABLE IF NOT EXISTS respaldo_incremental_20260812_cuotas LIKE cuotas;
CREATE TABLE IF NOT EXISTS respaldo_incremental_20260812_puntajes LIKE puntajes;

START TRANSACTION;

CREATE TEMPORARY TABLE src_incr_pagos (
  rut VARCHAR(20), anio INT, mes INT, monto_total INT, ref CHAR(64) PRIMARY KEY, fila_origen INT
) ENGINE=InnoDB;

CREATE TEMPORARY TABLE src_incr_detalle (
  ref CHAR(64), anio INT, mes INT, monto INT
) ENGINE=InnoDB;

CREATE TEMPORARY TABLE src_incr_puntaje (
  rut VARCHAR(20), anio INT, mes INT, puntos INT, detalle VARCHAR(200)
) ENGINE=InnoDB;

-- Solo crea el pago si NINGUNA de sus cuotas de destino ya tiene pago_detalle
-- previo (evita duplicar si este script se corre dos veces o si alguien ya
-- cargo manualmente uno de estos pagos por la app).
SELECT p.id, s.monto_total, 'migracion',
       STR_TO_DATE(CONCAT(s.anio,'-',LPAD(s.mes,2,'0'),'-01'),'%Y-%m-%d'),
       s.ref, 'mensual'
FROM src_incr_pagos s
JOIN personas p ON REPLACE(REPLACE(UPPER(TRIM(p.rut)), '.', ''), ' ', '') = s.rut
WHERE NOT EXISTS (
  SELECT 1 FROM src_incr_detalle d
  JOIN cuotas c ON c.persona_id = p.id AND c.anio = d.anio AND c.mes = d.mes
  JOIN pago_detalle pd ON pd.tipo = 'cuota' AND pd.referencia_id = c.id
  WHERE d.ref = s.ref
);

SELECT pg.id, 'cuota', c.id, d.monto
FROM src_incr_detalle d
JOIN pagos pg ON pg.referencia_externa = d.ref
JOIN src_incr_pagos s ON s.ref = d.ref
JOIN personas p ON REPLACE(REPLACE(UPPER(TRIM(p.rut)), '.', ''), ' ', '') = s.rut
JOIN cuotas c ON c.persona_id = p.id AND c.anio = d.anio AND c.mes = d.mes
WHERE NOT EXISTS (
  SELECT 1 FROM pago_detalle pd2 WHERE pd2.tipo = 'cuota' AND pd2.referencia_id = c.id AND pd2.pago_id <> pg.id
);

-- cuotas.estado solo admite pendiente/pagado/vencido (no existe 'parcial' en el
-- esquema real): igual que en la app en vivo, una cuota parcialmente pagada
-- queda tal cual hasta completarse; aqui solo se marca 'pagado' cuando corresponde.
UPDATE cuotas c
JOIN (SELECT referencia_id, SUM(monto_pagado) pagado FROM pago_detalle WHERE tipo = 'cuota' GROUP BY referencia_id) agr
  ON agr.referencia_id = c.id
JOIN src_incr_detalle d ON d.anio = c.anio AND d.mes = c.mes
JOIN src_incr_pagos s ON s.ref = d.ref
JOIN personas p ON REPLACE(REPLACE(UPPER(TRIM(p.rut)), '.', ''), ' ', '') = s.rut AND p.id = c.persona_id
SET c.estado = 'pagado'
WHERE c.estado <> 'pagado' AND agr.pagado >= c.monto;

-- Puntaje: respeta la UNIQUE KEY (cuota_id) — si la cuota ya tiene puntaje
-- cargado (por ejemplo por la app en vivo), esta fila se ignora.
SELECT p.id, c.id, sp.puntos, sp.detalle, CURDATE()
FROM src_incr_puntaje sp
JOIN personas p ON REPLACE(REPLACE(UPPER(TRIM(p.rut)), '.', ''), ' ', '') = sp.rut
JOIN cuotas c ON c.persona_id = p.id AND c.anio = sp.anio AND c.mes = sp.mes
WHERE c.estado = 'pagado';

COMMIT;

SELECT 'pagos_incrementales_insertados' control, COUNT(*) total FROM pagos WHERE referencia_externa IN (SELECT ref FROM src_incr_pagos)
UNION ALL SELECT 'pago_detalle_incrementales', COUNT(*) FROM pago_detalle pd JOIN pagos pg ON pg.id = pd.pago_id WHERE pg.referencia_externa IN (SELECT ref FROM src_incr_pagos)
UNION ALL SELECT 'cuotas_pagadas_por_incremento', COUNT(*) FROM cuotas c JOIN src_incr_detalle d ON d.anio=c.anio AND d.mes=c.mes JOIN src_incr_pagos s ON s.ref=d.ref JOIN personas p ON REPLACE(REPLACE(UPPER(TRIM(p.rut)), '.', ''), ' ', '')=s.rut AND p.id=c.persona_id WHERE c.estado='pagado'
UNION ALL SELECT 'puntajes_incrementales_insertados', COUNT(*) FROM puntajes WHERE detalle IN (SELECT detalle FROM src_incr_puntaje) AND fecha = CURDATE()
UNION ALL SELECT 'monto_total_insertado', COALESCE(SUM(monto_total),0) FROM pagos WHERE referencia_externa IN (SELECT ref FROM src_incr_pagos)
UNION ALL SELECT 'ruts_sin_match_en_personas', COUNT(*) FROM src_incr_pagos s WHERE NOT EXISTS (SELECT 1 FROM personas p WHERE REPLACE(REPLACE(UPPER(TRIM(p.rut)), '.', ''), ' ', '') = s.rut);
